def _monitor_loop(self):
    """监控循环"""
    while self._monitor_running:
        try:
            self._check_node_health()
            self._check_leader_availability()
            # 修复：定期更新存活节点的心跳
            current_time = time.time()
            with self._lock:
                for node in self.nodes.values():
                    if node.is_alive and node.is_healthy:
                        # 自动更新心跳
                        if current_time - node.last_heartbeat > self.heartbeat_interval:
                            node.last_heartbeat = current_time
            time.sleep(self.heartbeat_interval)
        except Exception as e:
            logger.error(f"监控循环错误: {e}")

async def handle_append_entries(self, request: AppendEntriesRequest) -> AppendEntriesResponse:
    """处理追加条目请求（完整实现）"""
    async with self._state_lock:
        # 任期检查
        if request.term > self._persistent_state.current_term:
            await self._become_follower(request.term)

        if request.term < self._persistent_state.current_term:
            return AppendEntriesResponse(
                term=self._persistent_state.current_term,
                follower_id=self.node_id,
                success=False,
                conflict_index=self._persistent_state.get_last_log_index(),
            )


        self._reset_election_timer()
        self._current_leader = request.leader_id

        # 日志一致性检查
        if request.prev_log_index >= 0:
            # 检查prev_log_index是否存在
            if request.prev_log_index >= len(self._persistent_state.log):
                return AppendEntriesResponse(
                    term=self._persistent_state.current_term,
                    follower_id=self.node_id,
                    success=False,
                    conflict_index=len(self._persistent_state.log),  # 告知Leader我们的日志长度
                )

            # 检查prev_log_term是否匹配
            entry = self._persistent_state.get_entry_at(request.prev_log_index)
            if entry is None or entry.term != request.prev_log_term:
                # 找到冲突任期
                conflict_term = entry.term if entry else 0
                conflict_index = request.prev_log_index

                # 优化：找到该任期的第一个索引，快速回退
                for i in range(request.prev_log_index, -1, -1):
                    e = self._persistent_state.get_entry_at(i)
                    if e and e.term != conflict_term:
                        conflict_index = i + 1
                        break

                return AppendEntriesResponse(
                    term=self._persistent_state.current_term,
                    follower_id=self.node_id,
                    success=False,
                    conflict_index=conflict_index,
                )


        # 追加新条目（处理冲突）
        for i, entry in enumerate(request.entries):
            index = request.prev_log_index + 1 + i

            if index < len(self._persistent_state.log):
                # 存在冲突，删除之后的所有条目
                if self._persistent_state.log[index].term != entry.term:
                    self._persistent_state.log = self._persistent_state.log[:index]
                    self._persistent_state.log.append(entry)
            else:
                self._persistent_state.log.append(entry)


        # 更新commit_index
        if request.leader_commit > self._volatile_state.commit_index:
            self._volatile_state.commit_index = min(
                request.leader_commit,
                self._persistent_state.get_last_log_index()
            )
            await self._apply_committed_entries()


        return AppendEntriesResponse(
            term=self._persistent_state.current_term,
            follower_id=self.node_id,
            success=True,
            match_index=request.prev_log_index + len(request.entries),
        )

class LeakyMemorySystem:
    """修复后的记忆系统"""

    def __init__(self, resource_tracker: ResourceTracker):
        self.resource_tracker = resource_tracker
        self.data: Dict[str, Any] = {}

        # 修复：使用字典管理定时器，支持按key清理
        self._timers: Dict[str, List[threading.Timer]] = {}  # key -> timers
        self._lock = threading.RLock()

    def create_memory(self, key: str, value: Any) -> bool:
        with self._lock:
            self.data[key] = value
            self.resource_tracker.register_object(value)

            # 创建定时器时记录key
            timer = threading.Timer(3600, lambda: None)
            timer.daemon = True
            timer.start()

            if key not in self._timers:
                self._timers[key] = []
            self._timers[key].append(timer)

            return True

    def delete_memory(self, key: str) -> bool:
        with self._lock:
            if key in self.data:
                del self.data[key]

                # 修复：取消并清理相关定时器
                if key in self._timers:
                    for timer in self._timers[key]:
                        timer.cancel()
                    del self._timers[key]

                return True
            return False

    def cleanup_all(self):
        """清理所有资源"""
        with self._lock:
            for timers in self._timers.values():
                for timer in timers:
                    timer.cancel()
            self._timers.clear()
            self.data.clear()
            gc.collect()

class ConnectionPool:
    """连接池管理"""

    def __init__(self, max_connections: int = 100):
        self._connections: Dict[int, Any] = {}
        self._key_to_connections: Dict[str, Set[int]] = {}
        self._lock = threading.Lock()
        self._max_connections = max_connections

    def acquire(self, key: str) -> int:
        """获取连接"""
        with self._lock:
            conn_id = id(object())  # 模拟连接ID
            self._connections[conn_id] = {'key': key, 'created_at': time.time()}

            if key not in self._key_to_connections:
                self._key_to_connections[key] = set()
            self._key_to_connections[key].add(conn_id)

            return conn_id

    def release(self, conn_id: int):
        """释放连接"""
        with self._lock:
            if conn_id in self._connections:
                key = self._connections[conn_id]['key']
                del self._connections[conn_id]
                if key in self._key_to_connections:
                    self._key_to_connections[key].discard(conn_id)

    def release_all(self, key: str):
        """释放指定key的所有连接"""
        with self._lock:
            if key in self._key_to_connections:
                for conn_id in list(self._key_to_connections[key]):
                    if conn_id in self._connections:
                        del self._connections[conn_id]
                del self._key_to_connections[key]

    def cleanup_all(self):
        """清理所有连接"""
        with self._lock:
            self._connections.clear()
            self._key_to_connections.clear()

class HotspotDetector:
    """热点检测器"""

    def __init__(self, threshold: int = 1000, window: float = 60.0):
        self._access_count: Dict[str, int] = {}
        self._threshold = threshold
        self._window = window
        self._lock = threading.Lock()
        self._hotspots: Set[str] = set()

    def record_access(self, key: str):
        """记录访问"""
        with self._lock:
            self._access_count[key] = self._access_count.get(key, 0) + 1

            if self._access_count[key] > self._threshold:
                self._hotspots.add(key)

    def is_hotspot(self, key: str) -> bool:
        """检查是否为热点"""
        with self._lock:
            return key in self._hotspots

    def get_replica_key(self, key: str) -> str:
        """获取副本key用于分散负载"""
        if self.is_hotspot(key):
            # 返回一个副本key
            replica_idx = hash(key + str(time.time() // self._window)) % 3
            return f"{key}:replica-{replica_idx}"
        return key
